(ns armate.archimate (:require [clojure.string :as s]))
(def call-re #"^([A-Za-z_]+)\s*\(([A-Za-z0-9_]+)\s*,\s*([A-Za-z0-9_]+)(?:\s*,\s*(.+?))?\)$")
(def quoted-split-re #"(\"[^\"]+\"|[^\"\s]+)")
(defn quoted-split [line] (map second (re-seq quoted-split-re line)))
(defn get-parts [line] (let [parts (quoted-split line)] (if (= (last parts) "{") {:parts (vec (drop-last parts)), :block? true} (let [lp (last parts)] (if (s/ends-with? lp "{") (let [cut-last (subs lp 0 (dec (count lp)))] {:parts (conj (vec (drop-last parts)) cut-last), :block? true}) (if-let [matches (re-matches call-re line)] {:parts (vec (rest matches)), :block? false} {:parts parts, :block? false}))))))
(defn cut1 [string] (subs string 1 (dec (count string))))
(defn cut2 [string] (cut1 (cut1 string)))
(defn wrapped? [start end part] (when part (and (s/starts-with? part start) (s/ends-with? part end))))
(def fur? (partial wrapped? "<<" ">>"))
(def fur-re #"(<<[^>]+>>|[^<>]+)")
(defn cut-fur [part] (->> (re-seq fur-re part) (map second) (map (fn* [%1] (if (fur? %1) (cut2 %1) %1)))))
(def quoted? (partial wrapped? "\"" "\""))
(defn cut-quotes [part] (if (quoted? part) (cut1 part) part))
(defn variable? [line] (and (s/starts-with? line "!") (not (s/starts-with? line "!include")) (s/includes? line "=")))
(def variable-re #"\!(.+?)\s*=\s*(.+)")
(defn parse-variable [line] (when (variable? line) (when-let [matches (re-matches variable-re line)] [(second matches) (cut-quotes (last matches))])))
(defn mask-specials [name] (reduce (fn [acc c] (s/replace acc (str c) (str "\\" c))) name [\^ \. \+ \* \? \[ \] \( \) \{ \} \- \$]))
(defn mask-variable [name] (let [checks [[(partial re-seq #"^[A-Za-z0-9]+") (fn* [%1] (str "\\b" %1))] [(partial re-seq #"[A-Za-z0-9]+$") (fn* [%1] (str %1 "\\b"))]]] (reduce (fn [acc [check replacement]] (if (check name) (replacement acc) acc)) (mask-specials name) checks)))
(defn apply-variables [variables line] (reduce-kv (fn [full k v] (let [re (re-pattern (mask-variable k))] (s/replace full re v))) line variables))
(defn get-blocks [content] (let [lines (s/split-lines content) indexes (map inc (range))] (loop [lines-is (map vector lines indexes) vars [] blocks [] outer-blocks (quote (nil))] (if (empty? lines-is) (if (seq outer-blocks) (throw (ex-info "Unclosed block" {:blocks (vec outer-blocks)})) blocks) (let [line-i (first lines-is) line (s/trim (first line-i)) index (second line-i) rest-lines-is (rest lines-is)] (if (or (empty? line) (s/starts-with? line "'")) (recur rest-lines-is vars blocks outer-blocks) (if-let [[name value] (parse-variable line)] (recur rest-lines-is (assoc vars name value) blocks outer-blocks) (let [full-line (apply-variables vars line) [[parts :parts] [block? :block?]] (get-parts full-line)] (if block? (recur rest-lines-is vars blocks (cons {:parts parts, :line index} outer-blocks)) (if (seq outer-blocks) (let [outer-block (first outer-blocks)] (if (= full-line "}") (if-let [prev-block (second outer-blocks)] (recur rest-lines-is vars blocks (cons (update prev-block :props (fnil conj []) outer-block) (rest (rest outer-blocks)))) (recur rest-lines-is vars (conj blocks outer-block) (rest outer-blocks))) (recur rest-lines-is vars blocks (cons (update outer-block :props (fnil conj []) {:parts parts, :line index}) (rest outer-blocks))))) (recur rest-lines-is vars (conj blocks {:parts parts, :line index}) outer-blocks)))))))))))
(def possible-relation-types #{:access_r :flow :access_w :triggering :specialization :association :serving :assignment :access_rw :access :aggregation :composition :influence :realization})
(def rel-f-re #"(?i)^Rel_(.+?)(?:_(?:Up|Down|Left|Right))?$")
(def rel-b-res [#"(?i)(.*?\.+)(?:up|down|left|right|u|d|l|r)(\.+.*)" #"(?i)(.*?-+)(?:up|down|left|right|u|d|l|r)(-+.*)" #"(.*?[\.\-]+)(.*)"])
(defn match-rel-b [dir-bond] (some (fn* [%1] (re-matches %1 dir-bond)) rel-b-res))
(def pin-re #"([^\.\-]*)?([\.\-]+)([^\.\-]*)?")
(defn match-pos-bond [mbond] (case mbond (["o" \- ""] ["O" \- ""]) {:type :aggregation} (["" \- "o"] ["" \- "O"]) {:type :aggregation, :reverse? true} ["" \- ""] {:type :association} ["*" \- ""] {:type :composition} ["" \- "*"] {:type :composition, :reverse? true} ["" \. ">>"] {:type :flow} ["<<" \. ""] {:type :flow, :reverse? true} ["" \. ">"] {:type :influence} ["<" \. ""] {:type :influence, :reverse? true} ["" \- ">"] {:type :serving} ["<" \- ""] {:type :serving, :reverse? true} (["" \- "|>"] ["" \- "^"]) {:type :specialization} (["<|" \- ""] ["^" \- ""]) {:type :specialization, :reverse? true} ["" \- ">>"] {:type :triggering} ["<<" \- ""] {:type :triggering, :reverse? true} {:type :unknown}))
(defn b-matches [dir-bond] (when-let [matches (match-rel-b dir-bond)] (let [bond (str (second matches) (last matches)) [_ left body right] (re-matches pin-re bond) bc (first body) mbond [left bc right]] (assoc (match-pos-bond mbond) :raw dir-bond :cut (apply str mbond)))))
(defn match-rel [parts] (when (> (count parts) 2) (let [[f s to desc] parts f-matches (re-matches rel-f-re f)] (if f-matches (let [kind (keyword (s/lower-case (second f-matches))) possible? (possible-relation-types kind) type (if possible? kind :unknown) result [[:type type] [:from s] [:to to] [:desc desc]]] (if possible? result (assoc result :raw f :cut kind))) (when-let [s-matches (b-matches s)] (merge s-matches {:desc desc} (if (:reverse? s-matches) {:from to, :to f} {:from f, :to to})))))))
(defn match-f? [first-word parts] (= (first parts) first-word))
(def match-start? (partial match-f? "@startuml"))
(def match-end? (partial match-f? "@enduml"))
(def match-include? (partial match-f? "!include"))
(def match-skinparam? (partial match-f? "skinparam"))
(def match-type? (partial match-f? "sprite"))
(def match-component? (partial match-f? "rectangle"))
(defn get-skinparam-target [parts] (let [tail (rest parts)] (if (empty? tail) [:default] (cut-fur (first tail)))))
(defn get-type-kind [parts] (keyword (s/replace-first (last parts) "jar:archimate/" "")))
(defn get-type-block [parts] {:kind (get-type-kind parts)})
(defn get-component-block [parts] (let [[shape title _as _alias type skin meta] parts [type3 skin2] (cut-fur type) skin3 (if skin2 skin2 (when (fur? skin) (cut2 skin))) meta3 (if meta meta (when-not (fur? skin) skin))] {:title (cut-quotes title), :shape shape, :type type3, :skin skin3, :meta meta3}))
(defn hidden-rel? [parts] (when-let [rel (second parts)] (s/includes? rel "[hidden]")))
(defn match-block [block] (let [parts (:parts block) line (:line block) body [[:line line]] result [[:body body]] rf (fn [& chain] (assoc result :in chain)) bf (fn [chain extra-body] (-> (apply rf chain) (update :body merge extra-body)))] (cond (match-start? parts) (let [result2 (rf :start)] (if (> (count parts) 1) (assoc-in result2 [:body :title] (cut-quotes (second parts))) result2)) (match-end? parts) (rf :end) (match-include? parts) (rf :includes (cut1 (second parts))) (match-skinparam? parts) (bf (cons :skins (get-skinparam-target parts)) {:props (:props block)}) (match-type? parts) (bf [:types (second parts)] (get-type-block parts)) (match-component? parts) (bf [:components (nth parts 3)] (assoc (get-component-block parts) :inside (map match-block (:props block)))) :else (when-not (hidden-rel? parts) (if-let [rel (match-rel parts)] (bf [:relations (:from rel) (:to rel)] rel) (bf [:unknowns] {:parts parts}))))))
(def possible-connections {:business-process {:business-event #{:triggering}, :business-function #{:flow :triggering :aggregation :composition}, :business-interaction #{:triggering :aggregation :composition}, :business-process #{:flow :triggering :aggregation :composition}, :business-service #{:realization}}, :application-interface {:application-service #{:assignment}, :application-component #{:flow}}, :business-event {:business-event #{:triggering :composition}, :business-function #{:triggering}, :business-interaction #{:triggering}, :business-process #{:triggering}}, :business-function {:business-event #{:triggering}, :business-function #{:flow :triggering :aggregation :composition}, :business-interaction #{:triggering :aggregation :composition}, :business-process #{:flow :triggering :aggregation :composition}, :business-service #{:realization}}, :application-component {:application-component #{:aggregation :composition}, :application-data-object #{:access_r :access_w :access_rw :access}, :application-function #{:assignment}, :application-interface #{:flow :triggering :composition}, :application-service #{:realization}}, :business-role {:business-function #{:assignment}, :business-process #{:assignment}, :business-role #{:specialization}}, :application-collaboration {:application-component #{:aggregation}, :application-interface #{:flow :composition}}, :business-collaboration {:business-interaction #{:assignment}, :business-role #{:aggregation}}, :business-product {:application-service #{:aggregation :composition}, :business-role #{:serving}, :business-service #{:aggregation :composition}}, :application-function {:application-service #{:realization}}, :application-service {:business-function #{:serving}, :business-process #{:serving}, :business-service #{:serving :realization}}, :business-service {:business-actor #{:serving}, :business-role #{:serving}}, :business-actor {:business-actor #{:composition}, :business-role #{:assignment}}, :technology-system-software {:application-interface #{:realization}, :application-component #{:serving}, :technology-system-software #{:aggregation :composition}}, :business-interaction {:business-function #{:triggering :aggregation :composition}, :business-interaction #{:triggering :aggregation :composition}, :business-process #{:triggering :aggregation :composition}}, :application-data-object {:application-data-object #{:specialization :association :aggregation :composition}}})
(def possible-components (set (concat (keys possible-connections) (mapcat keys (vals possible-connections)))))
(defn dissoc-if-nil [hm & ks] (apply dissoc hm (filter (fn* [%1] (nil? (hm %1))) ks)))
(defn append-matched-block [context block] (let [body (:body block) in (:in block) context-key (first in) err (fn [level kind bd] {:level level, :kind kind, :in in, :body bd}) add-err (fn [ctx level kind bd] (update ctx :lints conj (err level kind bd))) add-ctx (fn [ctx bd] (if (get-in ctx in) (-> ctx (add-err :error :duplicate bd) (update-in in merge bd)) (assoc-in ctx in bd))) lint-ctx (fn [ctx bd checks] (reduce (fn [cx [check [level kind] ctx-extra-check]] (if (and (or (not ctx-extra-check) (ctx-extra-check cx)) (check)) (add-err cx level kind bd) cx)) ctx checks))] (case context-key :unknowns (add-err context :error :unknown body) (:start :end :includes :skins) (add-ctx context body) :types (if (possible-components (:kind body)) (add-ctx context body) (-> context (add-err :warn :unsupporting-component-type body) (add-ctx body))) :components (let [[[type :type] [skin :skin] [meta :meta] [inside :inside]] body name (last in) kind (get-in context [:types type :kind]) body2 (assoc body :kind kind) checks (remove (comp nil? first) [[(when meta (fn* [] (not (#{"#Business" "#Application" "#Technology"} meta)))) [:warn :unsupporting-component-meta]] [(when skin (let [shape (:shape body)] (fn* [] (not (get-in context [:skins shape skin]))))) [:warn :undefined-component-skin]] [(fn* [] (nil? kind)) [:error :undefined-component-type]]]) linted-ctx (lint-ctx context body2 checks)] (reduce (fn [ctx inner-block] (let [inner-name (last (:in inner-block))] (-> (append-matched-block ctx inner-block) (append-matched-block {:in [:relations name inner-name], :body {:type :composition, :from name, :to inner-name}})))) (add-ctx linted-ctx body2) inside)) :relations (let [[[from :from] [to :to] [type :type]] body from-c (get-in context [:components from]) to-c (get-in context [:components to]) from-kind (:kind from-c) to-kind (:kind to-c) body2 (-> body (assoc :from (or from-kind from)) (assoc :to (or to-kind to)) (dissoc :cut) (dissoc-if-nil :desc)) checks [[(fn* [] (not (possible-relation-types type))) [:error :undefined-relation-type]] [(fn* [] (nil? from-c)) [:error :undefined-relation-from]] [(fn* [] (nil? to-c)) [:error :undefined-relation-to]] [(fn* [] (and (not (= :unknown type)) (not (contains? (get-in possible-connections [from-kind to-kind]) type)))) [:warn :unspecified-relation-type] (fn [ctx] (let [ll (last (:lints ctx))] (not (and (= in (:in ll)) (#{:undefined-relation-from :undefined-relation-to} (:kind ll))))))] [(fn* [] (get-in context [:relations to from])) [:warn :relation-between-components-already-present]]] linted-ctx (lint-ctx context body2 checks)] (add-ctx linted-ctx body2)))))
(defn append-block [context block] (if-let [matched-block (match-block block)] (append-matched-block context matched-block) context))
(defn finalize [context] (let [not-checks [[(fn* [] (get-in context [:includes "archimate/Archimate"])) [:warn :missing-archimate-include]] [(fn* [] (:end context)) [:warn :missing-end]] [(fn* [] (:start context)) [:warn :missing-start]]]] (reduce (fn [ctx [not-check [level kind]]] (if (not (not-check)) (update ctx :lints (partial concat [[[:level level] [:kind kind]]])) ctx)) context not-checks)))
(defn analyze [blocks] (finalize (reduce append-block {:start nil, :includes {}, :skins {}, :types {}, :components {}, :relations {}, :lints [], :end nil} blocks)))
(defn lint-content [content] (let [blocks (get-blocks content)] (:lints (analyze blocks))))
(defn lint [file-path] (let [content (slurp file-path)] (if (empty? content) (throw (ex-info "File is empty" {:file-path file-path})) (lint-content content))))
(comment)
